import 'package:flutter_test/flutter_test.dart';
import 'package:rafeeq_app/core/db/models.dart';
import 'package:rafeeq_app/features/quran/data/basmala.dart';

// GENERATED beside the real quran_local.db: every Arabic literal here
// is the database\u{2019}s own bytes, escaped codepoint by codepoint.
// Typing the basmala by hand does not match - the stored text uses
// U+0671 alef wasla, and al-Tin and al-Qadr add a shadda.

Ayah _ayah(int surah, int number, String text) => Ayah(
      id: surah * 1000 + number,
      surahId: surah,
      ayahNumber: number,
      textUthmani: text,
      pageNumber: 1,
      juzNumber: 1,
    );

void main() {
  group('basmala split', () {
    test('1:1 - al-Fatiha verse 1 IS the basmala and counts as a verse', () {
      final a = _ayah(1, 1, '\u{FEFF}\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650}');
      expect(basmalaOf(a), isNull);
      expect(bodyOf(a), a.textUthmani);
    });

    test('2:1 - al-Baqara opens with the basmala welded to the verse', () {
      final a = _ayah(2, 1, '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{627}\u{644}\u{653}\u{645}\u{653}');
      expect(basmalaOf(a), isNotNull);
      expect(bodyOf(a), isNot(a.textUthmani));
      expect(bodyOf(a), isNotEmpty);
      expect('${basmalaOf(a)} ${bodyOf(a)}', a.textUthmani);
    });

    test('9:1 - at-Tawbah has no basmala at all', () {
      final a = _ayah(9, 1, '\u{628}\u{64E}\u{631}\u{64E}\u{627}\u{653}\u{621}\u{64E}\u{629}\u{64C}\u{6ED} \u{645}\u{651}\u{650}\u{646}\u{64E} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{648}\u{64E}\u{631}\u{64E}\u{633}\u{64F}\u{648}\u{644}\u{650}\u{647}\u{650}\u{6E6}\u{653} \u{625}\u{650}\u{644}\u{64E}\u{649} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{64A}\u{646}\u{64E} \u{639}\u{64E}\u{670}\u{647}\u{64E}\u{62F}\u{62A}\u{651}\u{64F}\u{645} \u{645}\u{651}\u{650}\u{646}\u{64E} \u{671}\u{644}\u{652}\u{645}\u{64F}\u{634}\u{652}\u{631}\u{650}\u{643}\u{650}\u{64A}\u{646}\u{64E}');
      expect(basmalaOf(a), isNull);
      expect(bodyOf(a), a.textUthmani);
    });

    test('27:30 - an-Naml 30 quotes the basmala INSIDE the verse', () {
      final a = _ayah(27, 30, '\u{625}\u{650}\u{646}\u{651}\u{64E}\u{647}\u{64F}\u{6E5} \u{645}\u{650}\u{646} \u{633}\u{64F}\u{644}\u{64E}\u{64A}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{64E} \u{648}\u{64E}\u{625}\u{650}\u{646}\u{651}\u{64E}\u{647}\u{64F}\u{6E5} \u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650}');
      expect(basmalaOf(a), isNull);
      expect(bodyOf(a), a.textUthmani);
    });

    test('95:1 - al-Tin writes the basmala with a shadda', () {
      final a = _ayah(95, 1, '\u{628}\u{651}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{62A}\u{651}\u{650}\u{64A}\u{646}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{632}\u{651}\u{64E}\u{64A}\u{652}\u{62A}\u{64F}\u{648}\u{646}\u{650}');
      expect(basmalaOf(a), isNotNull);
      expect(bodyOf(a), isNot(a.textUthmani));
      expect(bodyOf(a), isNotEmpty);
      expect('${basmalaOf(a)} ${bodyOf(a)}', a.textUthmani);
    });

    test('97:1 - al-Qadr writes the basmala with a shadda', () {
      final a = _ayah(97, 1, '\u{628}\u{651}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{625}\u{650}\u{646}\u{651}\u{64E}\u{627}\u{653} \u{623}\u{64E}\u{646}\u{632}\u{64E}\u{644}\u{652}\u{646}\u{64E}\u{670}\u{647}\u{64F} \u{641}\u{650}\u{649} \u{644}\u{64E}\u{64A}\u{652}\u{644}\u{64E}\u{629}\u{650} \u{671}\u{644}\u{652}\u{642}\u{64E}\u{62F}\u{652}\u{631}\u{650}');
      expect(basmalaOf(a), isNotNull);
      expect(bodyOf(a), isNot(a.textUthmani));
      expect(bodyOf(a), isNotEmpty);
      expect('${basmalaOf(a)} ${bodyOf(a)}', a.textUthmani);
    });

    test('112:1 - al-Ikhlas, an ordinary short surah', () {
      final a = _ayah(112, 1, '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{642}\u{64F}\u{644}\u{652} \u{647}\u{64F}\u{648}\u{64E} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64F} \u{623}\u{64E}\u{62D}\u{64E}\u{62F}\u{64C}');
      expect(basmalaOf(a), isNotNull);
      expect(bodyOf(a), isNot(a.textUthmani));
      expect(bodyOf(a), isNotEmpty);
      expect('${basmalaOf(a)} ${bodyOf(a)}', a.textUthmani);
    });

    test('114:1 - an-Nas, the last surah', () {
      final a = _ayah(114, 1, '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{642}\u{64F}\u{644}\u{652} \u{623}\u{64E}\u{639}\u{64F}\u{648}\u{630}\u{64F} \u{628}\u{650}\u{631}\u{64E}\u{628}\u{651}\u{650} \u{671}\u{644}\u{646}\u{651}\u{64E}\u{627}\u{633}\u{650}');
      expect(basmalaOf(a), isNotNull);
      expect(bodyOf(a), isNot(a.textUthmani));
      expect(bodyOf(a), isNotEmpty);
      expect('${basmalaOf(a)} ${bodyOf(a)}', a.textUthmani);
    });

    // The whole mushaf: exactly 112 surahs carry a welded basmala,
    // and every split puts the verse back together verbatim.
    test('all 114 opening verses', () {
      const texts = <int, String>{
        1: '\u{FEFF}\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650}',
        2: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{627}\u{644}\u{653}\u{645}\u{653}',
        3: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{627}\u{644}\u{653}\u{645}\u{653}',
        4: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{64A}\u{64E}\u{670}\u{653}\u{623}\u{64E}\u{64A}\u{651}\u{64F}\u{647}\u{64E}\u{627} \u{671}\u{644}\u{646}\u{651}\u{64E}\u{627}\u{633}\u{64F} \u{671}\u{62A}\u{651}\u{64E}\u{642}\u{64F}\u{648}\u{627}\u{6DF} \u{631}\u{64E}\u{628}\u{651}\u{64E}\u{643}\u{64F}\u{645}\u{64F} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{649} \u{62E}\u{64E}\u{644}\u{64E}\u{642}\u{64E}\u{643}\u{64F}\u{645} \u{645}\u{651}\u{650}\u{646} \u{646}\u{651}\u{64E}\u{641}\u{652}\u{633}\u{64D}\u{6E2} \u{648}\u{64E}\u{670}\u{62D}\u{650}\u{62F}\u{64E}\u{629}\u{64D}\u{6E2} \u{648}\u{64E}\u{62E}\u{64E}\u{644}\u{64E}\u{642}\u{64E} \u{645}\u{650}\u{646}\u{652}\u{647}\u{64E}\u{627} \u{632}\u{64E}\u{648}\u{652}\u{62C}\u{64E}\u{647}\u{64E}\u{627} \u{648}\u{64E}\u{628}\u{64E}\u{62B}\u{651}\u{64E} \u{645}\u{650}\u{646}\u{652}\u{647}\u{64F}\u{645}\u{64E}\u{627} \u{631}\u{650}\u{62C}\u{64E}\u{627}\u{644}\u{64B}\u{6ED}\u{627} \u{643}\u{64E}\u{62B}\u{650}\u{64A}\u{631}\u{64B}\u{6ED}\u{627} \u{648}\u{64E}\u{646}\u{650}\u{633}\u{64E}\u{627}\u{653}\u{621}\u{64B}\u{6ED} \u{6DA} \u{648}\u{64E}\u{671}\u{62A}\u{651}\u{64E}\u{642}\u{64F}\u{648}\u{627}\u{6DF} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64E} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{649} \u{62A}\u{64E}\u{633}\u{64E}\u{627}\u{653}\u{621}\u{64E}\u{644}\u{64F}\u{648}\u{646}\u{64E} \u{628}\u{650}\u{647}\u{650}\u{6E6} \u{648}\u{64E}\u{671}\u{644}\u{652}\u{623}\u{64E}\u{631}\u{652}\u{62D}\u{64E}\u{627}\u{645}\u{64E} \u{6DA} \u{625}\u{650}\u{646}\u{651}\u{64E} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64E} \u{643}\u{64E}\u{627}\u{646}\u{64E} \u{639}\u{64E}\u{644}\u{64E}\u{64A}\u{652}\u{643}\u{64F}\u{645}\u{652} \u{631}\u{64E}\u{642}\u{650}\u{64A}\u{628}\u{64B}\u{6ED}\u{627}',
        5: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{64A}\u{64E}\u{670}\u{653}\u{623}\u{64E}\u{64A}\u{651}\u{64F}\u{647}\u{64E}\u{627} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{64A}\u{646}\u{64E} \u{621}\u{64E}\u{627}\u{645}\u{64E}\u{646}\u{64F}\u{648}\u{653}\u{627}\u{6DF} \u{623}\u{64E}\u{648}\u{652}\u{641}\u{64F}\u{648}\u{627}\u{6DF} \u{628}\u{650}\u{671}\u{644}\u{652}\u{639}\u{64F}\u{642}\u{64F}\u{648}\u{62F}\u{650} \u{6DA} \u{623}\u{64F}\u{62D}\u{650}\u{644}\u{651}\u{64E}\u{62A}\u{652} \u{644}\u{64E}\u{643}\u{64F}\u{645} \u{628}\u{64E}\u{647}\u{650}\u{64A}\u{645}\u{64E}\u{629}\u{64F} \u{671}\u{644}\u{652}\u{623}\u{64E}\u{646}\u{652}\u{639}\u{64E}\u{670}\u{645}\u{650} \u{625}\u{650}\u{644}\u{651}\u{64E}\u{627} \u{645}\u{64E}\u{627} \u{64A}\u{64F}\u{62A}\u{652}\u{644}\u{64E}\u{649}\u{670} \u{639}\u{64E}\u{644}\u{64E}\u{64A}\u{652}\u{643}\u{64F}\u{645}\u{652} \u{63A}\u{64E}\u{64A}\u{652}\u{631}\u{64E} \u{645}\u{64F}\u{62D}\u{650}\u{644}\u{651}\u{650}\u{649} \u{671}\u{644}\u{635}\u{651}\u{64E}\u{64A}\u{652}\u{62F}\u{650} \u{648}\u{64E}\u{623}\u{64E}\u{646}\u{62A}\u{64F}\u{645}\u{652} \u{62D}\u{64F}\u{631}\u{64F}\u{645}\u{64C} \u{6D7} \u{625}\u{650}\u{646}\u{651}\u{64E} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64E} \u{64A}\u{64E}\u{62D}\u{652}\u{643}\u{64F}\u{645}\u{64F} \u{645}\u{64E}\u{627} \u{64A}\u{64F}\u{631}\u{650}\u{64A}\u{62F}\u{64F}',
        6: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{671}\u{644}\u{652}\u{62D}\u{64E}\u{645}\u{652}\u{62F}\u{64F} \u{644}\u{650}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{649} \u{62E}\u{64E}\u{644}\u{64E}\u{642}\u{64E} \u{671}\u{644}\u{633}\u{651}\u{64E}\u{645}\u{64E}\u{670}\u{648}\u{64E}\u{670}\u{62A}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{652}\u{623}\u{64E}\u{631}\u{652}\u{636}\u{64E} \u{648}\u{64E}\u{62C}\u{64E}\u{639}\u{64E}\u{644}\u{64E} \u{671}\u{644}\u{638}\u{651}\u{64F}\u{644}\u{64F}\u{645}\u{64E}\u{670}\u{62A}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{646}\u{651}\u{64F}\u{648}\u{631}\u{64E} \u{6D6} \u{62B}\u{64F}\u{645}\u{651}\u{64E} \u{671}\u{644}\u{651}\u{64E}\u{630}\u{650}\u{64A}\u{646}\u{64E} \u{643}\u{64E}\u{641}\u{64E}\u{631}\u{64F}\u{648}\u{627}\u{6DF} \u{628}\u{650}\u{631}\u{64E}\u{628}\u{651}\u{650}\u{647}\u{650}\u{645}\u{652} \u{64A}\u{64E}\u{639}\u{652}\u{62F}\u{650}\u{644}\u{64F}\u{648}\u{646}\u{64E}',
        7: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{627}\u{644}\u{653}\u{645}\u{653}\u{635}\u{653}',
        8: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{64A}\u{64E}\u{633}\u{652}\u{640}\u{654}\u{64E}\u{644}\u{64F}\u{648}\u{646}\u{64E}\u{643}\u{64E} \u{639}\u{64E}\u{646}\u{650} \u{671}\u{644}\u{652}\u{623}\u{64E}\u{646}\u{641}\u{64E}\u{627}\u{644}\u{650} \u{6D6} \u{642}\u{64F}\u{644}\u{650} \u{671}\u{644}\u{652}\u{623}\u{64E}\u{646}\u{641}\u{64E}\u{627}\u{644}\u{64F} \u{644}\u{650}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{631}\u{651}\u{64E}\u{633}\u{64F}\u{648}\u{644}\u{650} \u{6D6} \u{641}\u{64E}\u{671}\u{62A}\u{651}\u{64E}\u{642}\u{64F}\u{648}\u{627}\u{6DF} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64E} \u{648}\u{64E}\u{623}\u{64E}\u{635}\u{652}\u{644}\u{650}\u{62D}\u{64F}\u{648}\u{627}\u{6DF} \u{630}\u{64E}\u{627}\u{62A}\u{64E} \u{628}\u{64E}\u{64A}\u{652}\u{646}\u{650}\u{643}\u{64F}\u{645}\u{652} \u{6D6} \u{648}\u{64E}\u{623}\u{64E}\u{637}\u{650}\u{64A}\u{639}\u{64F}\u{648}\u{627}\u{6DF} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{64E} \u{648}\u{64E}\u{631}\u{64E}\u{633}\u{64F}\u{648}\u{644}\u{64E}\u{647}\u{64F}\u{6E5}\u{653} \u{625}\u{650}\u{646} \u{643}\u{64F}\u{646}\u{62A}\u{64F}\u{645} \u{645}\u{651}\u{64F}\u{624}\u{652}\u{645}\u{650}\u{646}\u{650}\u{64A}\u{646}\u{64E}',
