        51: '\u{628}\u{650}\u{633}\u{652}\u{645}\u{650} \u{671}\u{644}\u{644}\u{651}\u{64E}\u{647}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{652}\u{645}\u{64E}\u{670}\u{646}\u{650} \u{671}\u{644}\u{631}\u{651}\u{64E}\u{62D}\u{650}\u{64A}\u{645}\u{650} \u{648}\u{64E}\u{671}\u{644}\u{630}\u{651}\u{64E}\u{670}\u{631}\u{650}\u{64A}\u{64E}\u{670}\u{62A}\u{650} \u{630}\u{64E}\u{631}\u{652}\u{648}\u{64B}\u{6ED}\u{627}',
